-- HordesRU v1.12: comprehensive skill-description translations.
-- One integrated module. Nothing in the original Hordes addon is modified.
-- Source: bonk_weapon table of the official Hordes of Azeroth 0.6.x server catalog.
local RU_ABILITY_DESCRIPTIONS = {
    ["Imp"] = "Призывает беса, который выпускает по 2 огненные стрелы во врагов в пределах 30 ярдов и поджигает их.", -- bonk_weapon 900
    ["Voidwalker"] = "Призывает демона Бездны. Он поглощает души умирающих рядом врагов и после 8 поглощений взрывается волной Бездны, поражая всех вокруг.", -- bonk_weapon 901
    ["Succubus"] = "Призывает суккуба. Её «Плеть боли» поражает всех врагов широким сектором перед ней и накладывает уязвимость к тьме.", -- bonk_weapon 902
    ["Felhunter"] = "Призывает охотника Скверны. «Теневой укус» наносит на 10% больше урона за каждый эффект порчи на цели и прерывает заклинания; «Теневой размах» бьёт врагов перед демоном. Каждые 10 сек. он снимает с вас вредный эффект.", -- bonk_weapon 903
    ["Corruption"] = "Поражает порчей 2 врагов в пределах 30 ярдов (в первую очередь без разложения). Накладывает 1 эффект разложения или 2, если его ещё не было.", -- bonk_weapon 904
    ["Curse of Agony"] = "Проклинает 2 врагов в пределах 30 ярдов, выбирая непоражённые цели с наибольшим запасом здоровья. Накладывает 1 эффект агонии (2 на ещё не проклятую цель). Ваши теневые стрелы добавляют по 1 эффекту агонии.", -- bonk_weapon 905
    ["Drain Life"] = "Вытягивает жизнь у ближайшего врага в 16 ярдах, нанося урон каждую секунду и восстанавливая вам 1% максимального здоровья за каждую цель (до 2%). Разложение и агония наносят этим врагам на 20% больше урона.", -- bonk_weapon 906
    ["Shadow Bolt"] = "Выпускает теневую стрелу в ближайшего врага. Урон повышается на 4% за каждый эффект разложения на цели (до 30). «Сумерки»: смерть врага под действием ваших проклятий выпускает бесплатную стрелу, не чаще раза в секунду.", -- bonk_weapon 907
    ["Immolate"] = "Поражает огнём 2 ближайших врагов, нанося урон и накладывая 2 эффекта горения.", -- bonk_weapon 908
    ["Hellfire"] = "Огненное пламя обжигает всех врагов в пределах 8 ярдов от вас, нанося урон и накладывая 1 эффект горения.", -- bonk_weapon 909
    ["Rain of Fire"] = "Обрушивает огненный дождь на самую большую группу врагов на 4 сек., нанося урон и накладывая по 1 эффекту горения каждую секунду.", -- bonk_weapon 910
    ["Fel Imps"] = "Призывает беса, выпускающего по 2 огненные стрелы в противников в радиусе 30 ярдов и поджигающего их. Стрелы перескакивают ещё на 2 цели в пределах 8 ярдов, нанося 60% урона.", -- bonk_weapon 911
    ["Imp Swarm"] = "Призывает беса, выпускающего по 2 огненные стрелы на расстояние до 30 ярдов и поджигающего врагов. Убитые стрелами противники призывают младших бесов на 6 сек. Одновременно может существовать до 6 бесов.", -- bonk_weapon 912
    ["Sacrifice"] = "Призывает демона Бездны, поглощающего души умирающих рядом врагов. После 8 поглощений он выпускает волну Бездны, поражающую всех вокруг, и даёт вам щит на 5% максимального здоровья.", -- bonk_weapon 913
    ["Void Slam"] = "Призывает демона Бездны. После 8 поглощённых врагов он выпускает поражающую всех вокруг волну Бездны. Каждые 6 сек. бьёт по земле в пределах 8 ярдов, отбрасывая обычных врагов.", -- bonk_weapon 914
    ["Painful Lash"] = "Призывает суккуба. Её «Плеть боли» бьёт всех врагов вокруг и накладывает уязвимость к тьме.", -- bonk_weapon 915
    ["Seduction"] = "Призывает суккуба. «Плеть боли» поражает врагов перед ней и накладывает уязвимость к тьме. Каждые 8 сек. суккуб притягивает сильнейшего обычного врага в радиусе 20 ярдов; 2 сек. тот получает двойной урон.", -- bonk_weapon 916
    ["Spell Lock"] = "Призывает охотника Скверны. «Теневой укус» получает +10% урона за каждый эффект порчи и прерывает заклинания всех врагов в радиусе 8 ярдов. «Теневой размах» поражает врагов перед демоном.", -- bonk_weapon 917
    ["Devour Affix"] = "Призывает охотника Скверны. «Теневой укус» получает +10% урона за каждый эффект порчи и отключает модификаторы элиты на 6 сек. (не чаще раза в 10 сек.). «Теневой размах» поражает врагов перед демоном.", -- bonk_weapon 918
    ["Seed of Corruption"] = "Поражает разложением 2 ближайших врагов. При смерти они взрываются и накладывают по 1 эффекту разложения на врагов в радиусе 6 ярдов. Взрывы могут вызвать ещё 2 цепных взрыва.", -- bonk_weapon 919
    ["Dark Harvest"] = "Накладывает по 1 эффекту разложения на 2 ближайших врагов. Каждые 6 сек. все поражённые враги в 30 ярдах мгновенно получают урон разложения за следующие 3 сек., сохраняя эффекты.", -- bonk_weapon 920
    ["Curse of Doom"] = "Проклинает агонией 2 врагов с наибольшим здоровьем. Через 10 сек. после первого проклятия «Рок» наносит огромный урон тьмой; если цель погибнет, страж ужаса сражается за вас 15 сек. Теневые стрелы добавляют по 1 эффекту агонии.", -- bonk_weapon 921
    ["Agony's Echo"] = "Проклинает агонией 2 врагов с наибольшим здоровьем. При смерти проклятой цели все эффекты агонии переходят ближайшему непроклятому врагу. Теневые стрелы добавляют по 1 эффекту агонии.", -- bonk_weapon 922
    ["Drain Soul"] = "Вытягивает жизнь из ближайшего врага в 16 ярдах каждую секунду, исцеляя вас до 2% макс. здоровья в секунду. Смерть поражённого врага даёт душу: +5% урона на 10 сек., до 10 душ. Разложение и агония наносят этой цели на 20% больше урона.", -- bonk_weapon 923
    ["Dark Pact"] = "Вытягивает жизнь ближайшего врага в 16 ярдах, нанося урон и исцеляя вас до 2% макс. здоровья в секунду. Избыточное исцеление увеличивает урон демонов на 30% на 4 сек. Разложение и агония наносят цели на 20% больше урона.", -- bonk_weapon 924
    ["Chaos Bolt"] = "Выпускает стрелу хаоса. Урон увеличивается на 4% за эффект разложения (до 30). Каждая 4-я стрела критически поражает цель и врагов в 8 ярдах с уроном 150%. «Сумерки»: смерть врагов под проклятиями выпускает бесплатную стрелу, не чаще раза в секунду.", -- bonk_weapon 925
    ["Shadow Barrage"] = "Выпускает теневую стрелу с +4% урона за эффект разложения (до 30). «Сумерки»: при смерти проклятых врагов выпускается бесплатная стрела не чаще раза в секунду, которая перескакивает на 2 соседние цели с половиной урона.", -- bonk_weapon 926
    ["Conflagrate"] = "Поражает 2 ближайших врагов огнём Скверны, накладывая 2 эффекта горения. Пламя распространяется на всех врагов в радиусе 5 ярдов от каждой цели с половиной урона и 1 эффектом горения.", -- bonk_weapon 927
    ["Shadowflame"] = "Поражает 2 ближайших врагов огнём Скверны, накладывая 2 эффекта горения и 1 эффект разложения.", -- bonk_weapon 928
    ["Inferno"] = "Пламя Скверны обжигает всех врагов в 8 ярдах и накладывает 1 эффект горения. По мере потери здоровья радиус кольца увеличивается максимум на 60%.", -- bonk_weapon 929
    ["Demonic Immolation"] = "Огонь Скверны обжигает врагов в 8 ярдах и накладывает 1 эффект горения. Ваши демоны также воспламеняются, нанося врагам в радиусе 6 ярдов половину урона.", -- bonk_weapon 930
    ["Summon Infernal"] = "4 сек. обрушивает огонь Скверны на самую большую группу врагов, накладывая горение. После дождя падает инфернал, наносит урон, оглушает обычных врагов в 6 ярдах на 1 сек. и сражается на вашей стороне 8 сек.", -- bonk_weapon 931
    ["Rain of Chaos"] = "4 сек. обрушивает огонь Скверны на 3 самые большие группы врагов, нанося урон и накладывая 1 эффект горения каждую секунду.", -- bonk_weapon 932
    ["Starfire"] = "Обрушивает звёздный свет на сильнейшего врага, нанося большой урон тайной магией. Усиливается в облике лунного совуха.", -- bonk_weapon 1001
    ["Moonfire"] = "Поражает тайной магией 2 врагов в радиусе 30 ярдов (сначала без Лунного огня) и накладывает 1 эффект Лунного огня. Усиливается в облике лунного совуха.", -- bonk_weapon 1002
    ["Hurricane"] = "4 сек. бушует буря над самой большой группой врагов, нанося урон природой каждую секунду и ошеломляя противников. Усиливается в облике лунного совуха.", -- bonk_weapon 1003
    ["Rake"] = "Раздирает 3 ближайших врагов, нанося урон и накладывая 2 эффекта кровотечения. Усиливается в облике кошки.", -- bonk_weapon 1004
    ["Shred"] = "Терзает врага с наибольшим числом кровотечений. Урон повышается на 3% за каждый эффект кровотечения. Усиливается в облике кошки.", -- bonk_weapon 1005
    ["Swipe"] = "Бьёт всех ближайших врагов. Усиливается в облике медведя.", -- bonk_weapon 1006
    ["Frenzied Regeneration"] = "Каждую секунду исцеляет вас на 0,25% максимального здоровья за каждого ближайшего врага (до 5). Усиливается в облике медведя.", -- bonk_weapon 1007
    ["Rejuvenation"] = "Каждую секунду восстанавливает 0,3% макс. здоровья и бьёт уроном природы 3 ближайших врагов в 10 ярдах. Избыточное исцеление ускоряет атаки и периодический урон на 15% на 3 сек. Усиливается в облике древа жизни.", -- bonk_weapon 1008
    ["Force of Nature"] = "Призывает 2 древней. Их удары накладывают Лунный огонь, а каждые 6 сек. они опутывают цель и обычных врагов в 5 ярдах на 2 сек. В облике древа жизни призывается ещё один древень.", -- bonk_weapon 1009
    ["Entangling Roots"] = "Опутывает 3 ближайших врагов в 25 ярдах, нанося урон природой и обездвиживая обычных врагов на 2 сек. Усиливается в облике древа жизни.", -- bonk_weapon 1010
    ["Tranquility"] = "На 4 сек. успокаивает воздух: каждую секунду наносит урон природой ближайшим врагам и исцеляет вас на 0,5% максимального здоровья. Усиливается в облике древа жизни.", -- bonk_weapon 1011
    ["Thorns"] = "Атакующие вас враги получают урон природой и 2 эффекта Лунного огня. Усиливается в облике медведя.", -- bonk_weapon 1012
    ["Starburst"] = "Обрушивает звёздный свет на сильнейшего врага, нанося большой урон тайной магией. Свет взрывается, поражая врагов рядом на 15% урона и накладывая Лунный огонь. Усиливается в облике совуха.", -- bonk_weapon 1014
    ["Shooting Stars"] = "Обрушивает звёздный свет на сильнейшего врага, нанося большой урон тайной магией. Враги под Лунным огнём могут дополнительно получить удар падающей звезды. Усиливается в облике совуха.", -- bonk_weapon 1015
    ["Sunfire"] = "Поражает 2 ближайших врагов тайной магией, накладывая 1 эффект Лунного огня. Лунный огонь распространяется ещё на 3 врагов рядом с каждой целью. Усиливается в облике совуха.", -- bonk_weapon 1016
    ["Full Moon"] = "Поражает 2 ближайших врагов тайной магией и накладывает Лунный огонь. Каждый 10-й эффект Лунного огня на враге вызывает «Полную луну», нанося урон тайной магией цели и врагам рядом. Усиливается в облике совуха.", -- bonk_weapon 1017
    ["Typhoon"] = "4 сек. над самой большой группой врагов бушует буря с уроном природой и ошеломлением каждую секунду. После окончания буря взрывается с двойным уроном и отбрасывает врагов. Усиливается в облике совуха.", -- bonk_weapon 1018
    ["Moonstorm"] = "4 сек. над самой большой группой врагов бушует буря с уроном природой и ошеломлением каждую секунду. Раз в 2 сек. накладывает Лунный огонь на врагов внутри. Усиливается в облике совуха.", -- bonk_weapon 1019
    ["Thrash"] = "Терзает всех ближайших врагов, нанося урон и накладывая 1 эффект кровотечения. Усиливается в облике кошки.", -- bonk_weapon 1020
    ["Tiger's Fury"] = "Раздирает 3 ближайших врагов, накладывая 2 эффекта кровотечения. Каждое попадание даёт +5% к скорости действий на 4 сек. (максимум +25%). Усиливается в облике кошки.", -- bonk_weapon 1021
    ["Mangle"] = "Терзает врага с наибольшим числом кровотечений (+3% урона за эффект) и дополнительно бьёт до 4 ближайших врагов на 25% урона. Усиливается в облике кошки.", -- bonk_weapon 1022
    ["Ferocious Bite"] = "Терзает врага с наибольшим числом кровотечений (+3% урона за эффект). Если цель погибла, атакует следующего врага с кровотечением, максимум 3 раза. Усиливается в облике кошки.", -- bonk_weapon 1023
    ["Lacerate"] = "Бьёт всех ближайших врагов и накладывает 1 эффект кровотечения. Усиливается в облике медведя.", -- bonk_weapon 1024
    ["Ursol's Vortex"] = "Бьёт всех ближайших врагов и оставляет вихрь на 3 сек., который каждую секунду наносит 50% урона и ошеломляет врагов внутри. Усиливается в облике медведя.", -- bonk_weapon 1025
    ["Bloody Frenzy"] = "Каждую секунду исцеляет на 0,25% максимального здоровья за каждого ближайшего врага (до 5). Каждое исцеление бьёт уроном до 5 ближайших врагов. Усиливается в облике медведя.", -- bonk_weapon 1026
    ["Barkskin"] = "Каждую секунду исцеляет на 0,25% максимального здоровья за каждого ближайшего врага (до 5). Каждое исцеление даёт щит на ту же величину (до 10% максимального здоровья). Усиливается в облике медведя.", -- bonk_weapon 1027
    ["Lifebloom"] = "Исцеляет вас на 0,3% максимального здоровья и бьёт уроном природы 3 ближайших врагов. Каждый 4-й цветок восстанавливает 1% здоровья и поражает всех врагов рядом. Избыточное исцеление ускоряет атаки заклинаний на 15% на 3 сек. Усиливается в облике древа жизни.", -- bonk_weapon 1028
    ["Efflorescence"] = "Создаёт у ваших ног цветочное кольцо на 4 сек. Находясь внутри, вы каждую секунду исцеляетесь на 0,3% максимального здоровья, а враги получают урон природой. Усиливается в облике древа жизни.", -- bonk_weapon 1029
    ["Ancient of War"] = "Призывает древня войны. Каждые 3 сек. он топает, нанося урон природой ближайшим врагам и накладывая Лунный огонь. Усиливается в облике древа жизни.", -- bonk_weapon 1030
    ["Fungal Growth"] = "Призывает 2 древней, чьи удары накладывают Лунный огонь и каждые 6 сек. опутывают врагов на 2 сек. В облике древа жизни +1 древень. Корни порождают грибы, взрывающиеся через 3 сек. с уроном природой.", -- bonk_weapon 1031
    ["Mass Entanglement"] = "Корни поражают уроном природы и опутывают 3 ближайших врагов на 2 сек. Затем распространяются на соседние цели. Усиливается в облике древа жизни.", -- bonk_weapon 1032
    ["Strangling Vines"] = "Корни наносят урон природой и опутывают 3 ближайших врагов на 2 сек. Опутанные враги получают урон каждую секунду и исцеляют вас на 0,05% максимального здоровья за цель (до 0,5% в сек.). Усиливается в облике древа жизни.", -- bonk_weapon 1033
    ["Widening Calm"] = "На 4 сек. создаёт волны покоя, ежесекундно наносящие урон природой и исцеляющие на 0,5% максимального здоровья. Радиус каждой волны увеличивается на 3 ярда. Усиливается в облике древа жизни.", -- bonk_weapon 1034
    ["Overgrowth"] = "На 4 сек. создаёт волны покоя, ежесекундно наносящие урон природой и исцеляющие на 0,5% максимального здоровья. Избыточное исцеление наносит до 60% дополнительного урона врагам рядом. Усиливается в облике древа жизни.", -- bonk_weapon 1035
    ["Brambles"] = "Атакующие вас враги получают урон природой и 2 эффекта Лунного огня. Шипы также поражают всех ближайших врагов половиной урона. Усиливается в облике медведя.", -- bonk_weapon 1036
    ["Nature's Grasp"] = "Атакующие вас враги получают урон природой и 2 эффекта Лунного огня, а также опутываются на 1 сек. Усиливается в облике медведя.", -- bonk_weapon 1037
    ["Crusader Strike"] = "Бьёт ближайшего врага с большим уроном и задевает противников в радиусе 5 ярдов от цели на 30% урона.", -- bonk_weapon 800
    ["Judgement"] = "Поражает 3 сильнейших врагов в 20 ярдах уроном света с удвоенным шансом критического удара. С печатью праведности урон +50%; с печатью повиновения задевает врагов в 5 ярдах от каждой цели половиной урона; с печатью света исцеляет на 1% здоровья за цель (до 5%).", -- bonk_weapon 801
    ["Seal of Command"] = "Каждый второй удар других заклинаний паладина выпускает вспышку света, поражающую цель и врагов в радиусе 5 ярдов уроном света.", -- bonk_weapon 802
    ["Seal of Righteousness"] = "Попадания других заклинаний паладина, включая урон по площади, наносят дополнительно 30% урона светом. «Правосудие» вместо этого получает +50% урона. На «Освящение», «Ауру воздаяния» и «Печать повиновения» не действует.", -- bonk_weapon 803
    ["Consecration"] = "Освящает землю под вами на 8 сек., нанося урон светом врагам внутри каждую секунду. Пока стоите на ней, наносите на 15% больше урона.", -- bonk_weapon 804
    ["Exorcism"] = "Наносит сильнейшему врагу в 30 ярдах большой урон светом. Нежить и демоны получают тройной урон, элита и боссы — двойной. Критические удары других заклинаний паладина сбрасывают перезарядку (не чаще раза в секунду).", -- bonk_weapon 805
    ["Divine Storm"] = "Вспышка света поражает всех врагов в 10 ярдах уроном света и исцеляет вас на 0,5% макс. здоровья за цель (до 3%). Каждое попадание считается ударом для печати повиновения (до 5 вспышек).", -- bonk_weapon 806
    ["Seal of Light"] = "Каждый удар других заклинаний паладина восстанавливает вам 0,5% максимального здоровья (не чаще 6 раз в секунду).", -- bonk_weapon 807
    ["Divine Shield"] = "Золотой купол блокирует следующий удар противника, который отнял бы более 5% максимального здоровья.", -- bonk_weapon 809
    ["Retribution Aura"] = "Каждую секунду наносит урон светом врагам в радиусе 10 ярдов. Ударившие вас враги получают двойной урон.", -- bonk_weapon 810
    ["Hammer of Justice"] = "Бросает молот в сильнейшего врага в пределах 20 ярдов, наносит урон светом и оглушает на 2 сек. На мини-боссов и боссов оглушение не действует.", -- bonk_weapon 811
    ["Light's Hammer"] = "Молоты света падают на 3 случайных врагов в радиусе 25 ярдов. Каждый поражает уроном света всех в пределах 5 ярдов.", -- bonk_weapon 812
    ["Avenger's Shield"] = "Бросает освящённый щит в ближайшего врага в 25 ярдах. Щит перескакивает ещё на 4 врагов в пределах 10 ярдов без повторных попаданий. Каждое попадание считается ударом паладина.", -- bonk_weapon 813
    ["Crusader's Zeal"] = "Наносит большой урон 2 ближайшим врагам и задевает врагов в пределах 5 ярдов от каждой цели половиной урона.", -- bonk_weapon 815
    ["Avenging Crusader"] = "Наносит ближайшему врагу большой урон и 30% этого урона окружающим в 5 ярдах. Каждый удар с шансом 15% выпускает «Молот гнева» с тем же уроном, добивая обычных врагов ниже 20% здоровья.", -- bonk_weapon 816
    ["Judgement of Light"] = "Поражает молотом света 3 сильнейших врагов в 20 ярдах, имея двойной шанс критического удара. Исцеляет вас на 1% здоровья за цель (до 5%) и активирует другие печати, как «Правосудие».", -- bonk_weapon 817
    ["Judgement of the Crusader"] = "Поражает молотом света 3 сильнейших врагов в 20 ярдах с двойным шансом критического удара. Осуждённые враги 6 сек. получают от вас на 20% больше урона. Активирует ваши печати, как «Правосудие».", -- bonk_weapon 818
    ["Seal of the Crusader"] = "Каждый удар других заклинаний паладина выпускает вспышку света, наносящую урон светом цели и врагам в пределах 5 ярдов.", -- bonk_weapon 819
    ["Seal of Justice"] = "Каждый второй удар других заклинаний паладина выпускает вспышку света по цели и врагам в пределах 5 ярдов, оглушая обычных и элитных врагов на 1 сек.", -- bonk_weapon 820
    ["Seal of the Templar"] = "Каждое попадание других заклинаний паладина, включая урон по площади, наносит дополнительно 60% урона светом.", -- bonk_weapon 821
    ["Seal of Vengeance"] = "Каждое попадание заклинаний паладина наносит дополнительно 30% урона светом. Урон возрастает на 20% с каждым последующим попаданием по той же цели (до 5 раз).", -- bonk_weapon 822
    ["Hallowed Ground"] = "Освящает землю под вами на 12 сек., нанося ежесекундный урон светом. Одновременно может действовать до 3 областей. Стоя на них, вы наносите на 25% больше урона.", -- bonk_weapon 823
    ["Blessed Ground"] = "Освящает землю под вами на 8 сек. Враги внутри ежесекундно получают урон светом; вы наносите на 15% больше урона и исцеляетесь на 0,5% максимального здоровья в секунду.", -- bonk_weapon 824
    ["Mass Exorcism"] = "Поражает 3 сильнейших врагов в 30 ярдах большим уроном света. Нежить и демоны получают тройной урон, элита и боссы — двойной. Критические удары других заклинаний паладина сбрасывают перезарядку (не чаще раза в секунду).", -- bonk_weapon 825
    ["The Art of War"] = "Наносит сильнейшему врагу в 30 ярдах большой урон света, а соседним в 5 ярдах — половину. Нежить и демоны получают тройной урон, элита и боссы — двойной. Критические удары паладина сбрасывают перезарядку не чаще раза в 0,5 сек.", -- bonk_weapon 826
    ["Divine Tempest"] = "Вспышка света поражает всех врагов в радиусе 12 ярдов и исцеляет вас на 0,5% максимального здоровья за цель (до 5%). Каждое попадание считается ударом печати повиновения.", -- bonk_weapon 827
    ["Wake of Ashes"] = "Вспышка света поражает всех врагов в 10 ярдах, замедляя обычных врагов на 50% и оглушая нежить и демонов на 1 сек. Исцеляет на 0,5% максимального здоровья за цель (до 3%). Каждое попадание считается ударом печати повиновения.", -- bonk_weapon 828
    ["Lay on Hands"] = "Удары других заклинаний паладина восстанавливают 0,5% максимального здоровья, не чаще 6 раз в секунду. При падении здоровья ниже 30% вы полностью исцеляетесь, не чаще раза в 90 сек.", -- bonk_weapon 829
    ["Illumination"] = "Удары других заклинаний паладина восстанавливают 0,5% максимального здоровья, не чаще 6 раз в секунду. Критические удары исцеляют втрое сильнее.", -- bonk_weapon 830
    ["Ardent Defender"] = "Золотой купол блокирует следующий удар, который отнял бы более 5% максимального здоровья. При падении здоровья ниже 30% вы становитесь неуязвимы на 2 сек., не чаще раза в 30 сек.", -- bonk_weapon 831
    ["Holy Shield"] = "Золотой купол блокирует следующий удар, который отнял бы более 5% максимального здоровья, и взрывается, нанося урон светом всем врагам в радиусе 10 ярдов.", -- bonk_weapon 832
    ["Sanctity Aura"] = "Ежесекундно обжигает уроном света всех врагов в 12 ярдах. Ударившие вас враги получают двойной урон.", -- bonk_weapon 833
    ["Devotion Aura"] = "Ежесекундно обжигает уроном света врагов в 10 ярдах. Ударившие вас получают двойной урон. Весь получаемый вами урон снижен на 10%.", -- bonk_weapon 834
    ["Hammer of the Righteous"] = "Бросает молот в сильнейшего врага в 20 ярдах, нанося урон светом ему и врагам в 6 ярдах, и оглушает цель на 2 сек. На боссов оглушение не действует.", -- bonk_weapon 835
    ["Repentance"] = "Бросает молоты в 3 сильнейших врагов в 20 ярдах, нанося урон светом и оглушая на 2 сек. Боссы не оглушаются.", -- bonk_weapon 836
    ["Shake the Heavens"] = "Молоты света падают на 5 случайных врагов в радиусе 25 ярдов, поражая уроном света всех врагов в 5 ярдах от каждого.", -- bonk_weapon 837
    ["Hammer of Light"] = "Молоты света падают на 3 случайных врагов в радиусе 25 ярдов, поражая врагов в 5 ярдах. Каждый третий раз дополнительный молот наносит тройной урон самой большой группе в пределах 10 ярдов.", -- bonk_weapon 838
    ["Grand Crusader"] = "Бросает освящённый щит в ближайшего врага в 25 ярдах. Щит перескакивает ещё на 8 врагов в радиусе 10 ярдов без повторных попаданий. Каждое попадание считается ударом паладина.", -- bonk_weapon 839
    ["Shield of the Righteous"] = "Бросает освящённый щит в ближайшего врага в 25 ярдах. Щит перескакивает ещё на 4 врагов в 10 ярдах, поражая соседних врагов в 5 ярдах половиной урона. Все попадания считаются ударами паладина.", -- bonk_weapon 840
    ["Lightning Bolt"] = "Бросает молнию в ближайшего врага, после чего она перескакивает ещё на одну цель. Каждое попадание наносит урон природой и накладывает 1 заряд статики.", -- bonk_weapon 700
    ["Chain Lightning"] = "Бросает молнию в ближайшего врага. Она перескакивает ещё на 4 цели, нанося урон природой и накладывая по 1 заряду статики.", -- bonk_weapon 701
    ["Flame Shock"] = "Поражает сильнейшего врага поблизости (сначала элиту) уроном огня и накладывает 6 эффектов горения.", -- bonk_weapon 702
    ["Earth Shock"] = "Поражает врага с наибольшим числом зарядов статики уроном природы (+50% за каждый заряд). Поглощает заряды, задевая до 3 врагов рядом. Каждый поглощённый заряд восстанавливает 1 заряд щита молний.", -- bonk_weapon 703
    ["Windfury Weapon"] = "Бьёт ближайшего врага. Каждый третий удар активирует «Неистовство ветра»: 2 дополнительных удара, также задевающих врагов в 4 ярдах от цели.", -- bonk_weapon 704
    ["Stormstrike"] = "Дважды поражает ближайшего врага в 12 ярдах оружием и молнией, накладывая 2 заряда статики и 2 эффекта уязвимости к природе. Считается за 2 удара «Оружия водоворота».", -- bonk_weapon 705
    ["Maelstrom Weapon"] = "Каждое третье попадание других заклинаний шамана и укусов духов волков выпускает бесплатную молнию в ближайшего врага в 30 ярдах или в 3 ближайших при наличии «Цепной молнии». Наносит урон природой и накладывает 1 заряд статики. Щит молний и тотемы не учитываются.", -- bonk_weapon 706
    ["Feral Spirit"] = "Призывает 2 духов волков, укусы которых накладывают по 1 заряду статики. Каждые 3 сек. каждый волк бьёт всех врагов перед собой в радиусе 6 ярдов.", -- bonk_weapon 707
    ["Searing Totem"] = "Ставит обжигающий тотем у ваших ног. Тотем стреляет огнём по 2 врагам в 20 ярдах и поджигает их. При удалении от него тотем переставляется.", -- bonk_weapon 708
    ["Magma Totem"] = "Бросает тотем магмы в самую большую группу врагов в 25 ярдах. Каждые 2 сек. он наносит урон огнём и накладывает горение в радиусе 8 ярдов. Если поблизости нет целей, тотем перебрасывается.", -- bonk_weapon 709
    ["Healing Stream Totem"] = "Ставит тотем исцеляющего потока у ваших ног. Пока вы в радиусе 15 ярдов от него, каждую секунду восстанавливается 1% максимального здоровья.", -- bonk_weapon 710
    ["Lightning Shield"] = "Окружает вас 3 зарядами молний. Каждые 1,5 сек. каждый заряд поражает врага в 10 ярдах уроном природы и статикой, давая щит на 0,5% здоровья (до 5%). Ударивший вас враг расходует заряд и получает разряд. Заряды восстанавливаются по одному раз в 1,5 сек.", -- bonk_weapon 711
    ["Lightning Overload"] = "Бросает молнию в ближайшего врага, нанося урон природой и накладывая статику. Если удар вызвал разряд статики, из цели дополнительно вылетает цепная молния.", -- bonk_weapon 712
    ["Lava Burst"] = "Бросает лаву во врага с наибольшим числом эффектов горения. Горящие враги всегда получают критический удар.", -- bonk_weapon 713
    ["Elemental Mastery"] = "Бросает молнию, перескакивающую до 10 раз и наносящую урон природой и 1 заряд статики каждой цели. Каждое перескакивание уменьшает урон на 15%.", -- bonk_weapon 714
    ["Forked Lightning"] = "Выпускает цепную молнию в 2 ближайших врагов. Каждая перескакивает ещё на 4 цели, нанося урон природой и по 1 заряду статики.", -- bonk_weapon 715
    ["Frost Shock"] = "Поражает сильнейшего врага поблизости (сначала элиту) уроном льда и накладывает 6 эффектов охлаждения.", -- bonk_weapon 716
    ["Lava Surge"] = "Поражает сильнейшего врага поблизости уроном огня и накладывает 6 эффектов горения. При смерти горящих врагов немедленно вылетает молния.", -- bonk_weapon 717
    ["Earthquake"] = "Поражает врага с наибольшей статикой (+50% урона природы за заряд), расходуя заряды и задевая до 3 соседних врагов. Земля сотрясается 4 сек., ежесекундно нанося урон природой и ошеломляя врагов. Каждый потраченный заряд восстанавливает 1 заряд щита молний.", -- bonk_weapon 718
    ["Eye of the Storm"] = "Поражает врага с наибольшей статикой (+50% урона природы за заряд), расходует заряды и задевает до 3 соседних врагов. Все разряды статики в 10 ярдах также бьют врагов в радиусе 6 ярдов. Каждый потраченный заряд восстанавливает 1 заряд щита молний.", -- bonk_weapon 719
    ["Flametongue Weapon"] = "Бьёт ближайшего врага с дополнительным уроном огня и 1 эффектом горения. Каждый третий удар вызывает 2 дополнительных удара неистовства ветра, поражающих врагов в 4 ярдах и накладывающих по 3 эффекта горения.", -- bonk_weapon 720
    ["Doom Winds"] = "Бьёт ближайшего врага. Каждый третий удар вызывает 2 дополнительных удара неистовства ветра по врагам в 4 ярдах. Раз в 15 сек. на 4 сек. каждый удар вызывает неистовство ветра.", -- bonk_weapon 721
    ["Lava Lash"] = "Дважды поражает ближайшего врага в 12 ярдах оружием и лавой, накладывая 2 заряда статики, 2 эффекта уязвимости к природе и 2 эффекта горения. Лава наносит горящим врагам на 50% больше урона. Считается за 2 удара «Оружия водоворота».", -- bonk_weapon 722
    ["Crash Lightning"] = "Дважды поражает ближайшего врага в 12 ярдах оружием и молнией, накладывая 2 заряда статики и 2 уязвимости к природе. Молния также бьёт врагов в 8 ярдах от вас и накладывает статику. Считается за 2 удара «Оружия водоворота».", -- bonk_weapon 723
    ["Overcharge"] = "Каждый третий удар других заклинаний шамана или духов волков выпускает бесплатную молнию в 3 ближайших врагов (в 5 с «Цепной молнией»). Наносит урон природой. Удары тотемов не учитываются.", -- bonk_weapon 724
    ["Static Surge"] = "Каждый третий удар шамана или духов волков выпускает бесплатную молнию в ближайшего врага (в 3 с «Цепной молнией») и накладывает 5 зарядов статики для немедленного разряда. Удары тотемов не учитываются.", -- bonk_weapon 725
    ["Elemental Spirits"] = "Призывает 2 духов волков в обликах огня, льда и молнии. Укусы накладывают соответственно горение, охлаждение или статику.", -- bonk_weapon 726
    ["Spirit Pack"] = "Призывает 2 духов волков, укусы которых накладывают статику. Каждое неистовство ветра призывает дополнительного волка на 6 сек.", -- bonk_weapon 727
    ["Fire Nova Totem"] = "Ставит обжигающий тотем у ваших ног, стреляющий огнём по врагу в 20 ярдах и поджигающий его. Каждые 4 сек. тотем взрывается огнём в радиусе 8 ярдов, накладывая 3 эффекта горения, и переставляется.", -- bonk_weapon 728
    ["Totem of Wrath"] = "Ставит обжигающий тотем, стреляющий по 2 врагам в 20 ярдах и поджигающий их. Враги в радиусе 15 ярдов от тотема получают на 15% больше урона огнём.", -- bonk_weapon 729
    ["Liquid Magma"] = "Бросает тотем магмы в крупнейшую группу врагов в 25 ярдах. Каждые 2 сек. наносит урон огнём и накладывает горение в радиусе 8 ярдов. Каждый импульс дополнительно выпускает 2 сгустка магмы по врагам в 12 ярдах. При отсутствии целей тотем перебрасывается.", -- bonk_weapon 730
    ["Earthbind"] = "Бросает тотем магмы в крупнейшую группу врагов в 25 ярдах. Каждые 2 сек. наносит урон огнём и накладывает горение и ошеломление в 8 ярдах. При отсутствии целей тотем перебрасывается.", -- bonk_weapon 731
    ["Healing Tide"] = "Призывает тотем исцеляющего прилива, который следует за вами и каждую секунду восстанавливает 1% максимального здоровья.", -- bonk_weapon 732
    ["Healing Rain"] = "Ставит тотем исцеляющего потока. В радиусе 15 ярдов он каждую секунду восстанавливает вам 1% здоровья. Каждые 3 сек. дождь наносит урон природой врагам в 10 ярдах.", -- bonk_weapon 733
    ["Earth Shield"] = "Окружает вас 3 зарядами молний. Каждые 1,5 сек. каждый заряд бьёт врага в 10 ярдах и даёт щит на 1,5% максимального здоровья (до 15%). Ударивший вас враг расходует заряд и получает разряд. Один заряд восстанавливается каждые 1,5 сек.", -- bonk_weapon 734
    ["Static Shock"] = "Окружает вас 3 зарядами молний. Каждые 1,5 сек. каждый заряд поражает врага в 10 ярдах и соседние цели в 4 ярдах уроном природы и статикой, давая щит на 0,5% здоровья (до 5%). Вражеские удары и ваши атаки ближнего боя расходуют заряд на дополнительный разряд. Заряды восстанавливаются каждые 1,5 сек.", -- bonk_weapon 735
    ["Sinister Strike"] = "Наносит урон ближайшему врагу ударом клинка.", -- bonk_weapon 600
    ["Blade Flurry"] = "На 8 сек. ваши удары по одиночным целям дополнительно поражают ещё 4 врагов в радиусе 8 ярдов с 50% урона. Дополнительные удары переносят яды и начальные атаки.", -- bonk_weapon 601
    ["Eviscerate"] = "Наносит ближайшему врагу большой урон с удвоенным шансом критического удара. После убийства атака переходит на следующего врага в 8 ярдах, до 3 раз.", -- bonk_weapon 602
    ["Killing Spree"] = "За 1,4 сек. наносит 8 ударов по случайным врагам в 10 ярдах. Каждый удар переносит яды и начальные атаки и сокращает перезарядку «Потрошения» на 0,5 сек.", -- bonk_weapon 603
    ["Mutilate"] = "Бьёт ближайшего врага обоими кинжалами. Каждый удар накладывает 1 эффект яда и ещё 1 за каждые 5 уже имеющихся. Отравленным целям наносит на 30% больше урона.", -- bonk_weapon 604
    ["Deadly Poison"] = "Ваши способности накладывают по 1 эффекту яда при каждом попадании. Дополнительно бросает флакон в крупнейшую группу врагов в 20 ярдах: урон природой и 4 эффекта яда всем в 8 ярдах.", -- bonk_weapon 605
    ["Fan of Knives"] = "Бросает клинки во все стороны, поражая врагов в радиусе 10 ярдов и накладывая 2 эффекта яда. Все клинки переносят ваши яды и начальные атаки.", -- bonk_weapon 606
    ["Envenom"] = "Поражает 3 врагов с наибольшим количеством яда уроном природой и всем оставшимся периодическим уроном их яда. Эффекты сохраняются. Ваши удары 5 сек. накладывают на 2 эффекта яда больше.", -- bonk_weapon 607
    ["Shuriken Toss"] = "Бросает сюрикены в 3 ближайших врагов в 20 ярдах, выбирая сначала ещё не поражённых вами.", -- bonk_weapon 608
    ["Ambush"] = "Первое попадание ваших других способностей по каждому врагу вызывает дополнительную «Внезапную атаку» с большим уроном и двойным шансом критического удара.", -- bonk_weapon 609
    ["Shadow Dance"] = "На 4 сек. ваши удары наносят на 30% больше урона и снова могут вызывать «Внезапную атаку» раз в секунду на каждого врага.", -- bonk_weapon 610
    ["Evasion"] = "На 5 сек. увеличивает вероятность уклонения на 50%, максимум до 85%.", -- bonk_weapon 611
    ["Main Gauche"] = "Наносит урон ближайшему врагу, затем бьёт оружием во второй руке другого врага в пределах 8 ярдов.", -- bonk_weapon 612
    ["Saber Slash"] = "Наносит урон ближайшему врагу. Если удар убил цель, мгновенно поражает следующего врага, до 3 раз подряд.", -- bonk_weapon 613
    ["Endless Flurry"] = "Ваши удары по одиночной цели всегда дополнительно поражают 2 врагов в 8 ярдах с половиной урона. Дополнительные удары переносят яды и начальные атаки.", -- bonk_weapon 614
    ["Shadow Blades"] = "На 8 сек. ваши удары по одиночным целям задевают ещё 4 врагов в 8 ярдах, нанося 50% урона тьмой. Дополнительные удары могут снова вызвать «Внезапную атаку» раз в секунду на врага.", -- bonk_weapon 615
    ["Coup de Grace"] = "Наносит большой урон 5 ближайшим врагам с двойным шансом критического удара. При убийстве атака переходит к следующему врагу в 8 ярдах, до 3 раз.", -- bonk_weapon 616
    ["Deadly Throw"] = "Бросает клинок в сильнейшего врага в 30 ярдах (сначала элиту), нанося большой урон с удвоенным шансом критического удара. Обычных врагов замедляет на 50% на 3 сек. Убийство переносит атаку на следующую цель в 8 ярдах, до 3 раз.", -- bonk_weapon 617
    ["Murderous Intent"] = "За 2 сек. наносит 8 ударов по случайным врагам в 10 ярдах. Каждое убийство добавляет 2 удара (до 20 дополнительных). Каждый удар сокращает перезарядку «Потрошения» на 0,5 сек.", -- bonk_weapon 618
    ["Grand Finale"] = "За 2 сек. наносит 8 ударов по случайным врагам в 10 ярдах. Последний удар бесплатно активирует «Потрошение» и «Отравление», если они известны. Каждый удар сокращает перезарядку «Потрошения» на 0,5 сек.", -- bonk_weapon 619
    ["Toxic Blade"] = "Бьёт обоими кинжалами. Каждый удар накладывает 1 эффект яда (ещё 1 за каждые 5 уже имеющихся) и 2 эффекта уязвимости к природе. Отравленным врагам наносит на 30% больше урона.", -- bonk_weapon 620
    ["Blindside"] = "Бьёт ближайшего врага обоими кинжалами, а ниже 35% здоровья — трижды. Каждый удар накладывает 1 эффект яда (ещё 1 за каждые 5 на цели). Отравленным врагам наносит на 30% больше урона.", -- bonk_weapon 621
    ["Crippling Poison"] = "Ваши способности накладывают яд при каждом ударе и замедляют обычных врагов на 30%. Отравленные получают от вас на 15% больше урона. Дополнительно бросает флакон в крупнейшую группу в 20 ярдах, нанося урон природой и 4 эффекта яда в радиусе 8 ярдов.", -- bonk_weapon 622
    ["Instant Poison"] = "Ваши способности накладывают яд при каждом ударе и наносят дополнительно 30% урона природой. Дополнительно бросает флакон в крупнейшую группу врагов в 20 ярдах, нанося урон природой и 4 эффекта яда в 8 ярдах.", -- bonk_weapon 623
    ["Caltrops"] = "Бросает ножи во все стороны, поражая врагов в 10 ярдах и накладывая по 2 эффекта яда. На 4 сек. остаются шипы, замедляющие врагов и ежесекундно накладывающие 1 эффект яда.", -- bonk_weapon 624
    ["Deadly Fan"] = "Бросает ножи во все стороны, поражая врагов в 10 ярдах и накладывая 2 эффекта яда. Также срабатывает при «Потрошении» или «Отравлении».", -- bonk_weapon 625
    ["Venom Splash"] = "Поражает 3 врагов с наибольшим ядом уроном природой и всем оставшимся уроном яда, сохраняя эффекты. Также бьёт всех отравленных врагов в 8 ярдах от целей. Ваши удары 5 сек. накладывают на 2 эффекта яда больше.", -- bonk_weapon 626
    ["Exsanguinate"] = "Поражает 3 врагов с наибольшим ядом уроном природой и оставшимся периодическим уроном яда, сохраняя эффекты. Эти враги и все отравленные в 10 ярдах мгновенно получают урон яда за следующие 4 сек. Ваши удары 5 сек. накладывают +2 эффекта яда.", -- bonk_weapon 627
    ["Shuriken Storm"] = "Бросает сюрикены в 2 ближайших врагов в 20 ярдах, сначала в ещё не поражённых. Каждый сюрикен перескакивает ещё на 2 врагов.", -- bonk_weapon 628
    ["Shadowy Shuriken"] = "Бросает сюрикены в 2 ближайших врагов в 20 ярдах. На месте попадания остаётся тень, которая через 1,5 сек. взрывается уроном тьмы в 5 ярдах.", -- bonk_weapon 629
    ["Cheap Shot"] = "Первый удар ваших способностей по врагу вызывает «Внезапную атаку» с большим уроном и двойным шансом критического удара. «Внезапная атака» оглушает обычных врагов на 1 сек.", -- bonk_weapon 630
    ["Find Weakness"] = "Первый удар ваших способностей по врагу вызывает «Внезапную атаку» с большим уроном и двойным шансом критического удара. После неё враг 6 сек. получает от вас на 20% больше урона.", -- bonk_weapon 631
    ["Vanish"] = "На 4 сек. урон ударов повышен на 30%, и они снова могут вызывать «Внезапную атаку» раз в секунду на цель. В начале вы исчезаете: обычные враги в 10 ярдах теряют вас из виду и ошеломляются на 2 сек.", -- bonk_weapon 632
    ["Symbols of Death"] = "На 4 сек. ваши удары наносят на 30% больше урона и снова могут вызывать «Внезапную атаку» раз в секунду на цель. При активации теневой удар поражает 5 сильнейших врагов в 14 ярдах.", -- bonk_weapon 633
    ["Riposte"] = "На 5 сек. шанс уклонения увеличен на 50%. Каждое уклонение наносит ответный удар противнику.", -- bonk_weapon 634
    ["Smoke Bomb"] = "На 5 сек. шанс уклонения увеличен на 50%. Пока вы находитесь в дыму у ваших ног, атаки врагов промахиваются в половине случаев.", -- bonk_weapon 635
    ["Smite"] = "Поражает 2 ближайших врагов уроном света. Каждый удар сокращает перезарядку «Слова Света: Наказание» на 1 сек.", -- bonk_weapon 500
    ["Renew"] = "Каждую секунду восстанавливает 1% максимального здоровья. При полном здоровье вместо этого бьёт ближайшего врага в 30 ярдах уроном света. При наличии «Слова Силы: Щит» избыточное исцеление пополняет щит до его размера.", -- bonk_weapon 501
    ["Halo"] = "Кольцо света поражает уроном света всех врагов в 12 ярдах от вас и исцеляет на 0,5% максимального здоровья за цель (до 2%).", -- bonk_weapon 502
    ["Holy Word: Chastise"] = "Свет поражает сильнейшего врага в радиусе 30 ярдов большим уроном света. Каждое «Наказание» или «Кольцо света» сокращает перезарядку на 1 сек.", -- bonk_weapon 503
    ["Power Word: Shield"] = "Создаёт щит на 10% максимального здоровья. Повторное применение восстанавливает его, а не складывает щиты. Пока щит действует, скорость движения увеличена на 10%.", -- bonk_weapon 504
    ["Penance"] = "Выпускает 3 световые стрелы во врагов, атаковавших вас за последние 5 сек., или ближайших. Каждая наносит урон светом и восстанавливает 0,5% максимального здоровья. Избыточное исцеление создаёт щит до 6% максимального здоровья.", -- bonk_weapon 505
    ["Psychic Scream"] = "Обычные враги в 8 ярдах на 2 сек. бегут в страхе и каждую секунду получают урон тьмой. Элита и боссы невосприимчивы.", -- bonk_weapon 506
    ["Shackle"] = "Поражает сильнейшего врага в 30 ярдах уроном света и связывает на 2 сек., нанося периодический урон. В первую очередь выбирает боссов и мини-боссов, но их нельзя связать.", -- bonk_weapon 507
    ["Shadow Word: Pain"] = "Накладывает 6 эффектов разложения на 3 самых дальних врагов в пределах 35 ярдов.", -- bonk_weapon 508
    ["Mind Flay"] = "Истязает ближайшего врага в 20 ярдах уроном тьмы, накладывает разложение и замедляет на 30%. Продолжается до смерти цели или выхода из радиуса. Урон +5% за эффект разложения (до 30).", -- bonk_weapon 509
    ["Mind Blast"] = "Поражает уроном тьмы врага с наибольшим числом эффектов разложения. Все враги в 8 ярдах от него получают такое же количество эффектов (до 10).", -- bonk_weapon 510
    ["Shadowfiend"] = "Призывает исчадие Тьмы, атаки которого накладывают разложение, а теневой размах бьёт всех врагов перед ним. Его удары восстанавливают вам 0,5% максимального здоровья.", -- bonk_weapon 511
    ["Holy Fire"] = "Поражает ближайшего врага священным огнём, нанося урон светом и накладывая 3 эффекта горения. Каждое «Наказание» сокращает перезарядку «Слова Света: Наказание» на 1 сек.", -- bonk_weapon 512
    ["Searing Light"] = "Поражает ближайшего врага уроном света. Каждое 4-е «Наказание» поражает врагов в 6 ярдах и оглушает обычных на 1 сек. Каждое «Наказание» сокращает перезарядку «Слова Света: Наказание» на 1 сек.", -- bonk_weapon 513
    ["Echo of Light"] = "Каждую секунду исцеляет вас на 1% здоровья. При полном здоровье поражает ближайшего врага в 30 ярдах уроном света. Избыточное исцеление дополнительно бьёт врага до 2 раз в секунду и при наличии «Слова Силы: Щит» пополняет щит.", -- bonk_weapon 514
    ["Prayer of Mending"] = "Каждую секунду исцеляет вас на 1% здоровья. При полном здоровье поражает ближайшего врага в 30 ярдах уроном света с переходом на 2 соседние цели. При наличии «Слова Силы: Щит» избыточное исцеление пополняет щит.", -- bonk_weapon 515
    ["Divine Hymn"] = "За 2 сек. создаёт 3 волны света, наносящие урон света всем врагам в 12 ярдах и исцеляющие вас на 0,5% максимального здоровья за цель (до 2%).", -- bonk_weapon 516
    ["Light's Edge"] = "Кольцо света поражает врагов в 12 ярдах уроном света (до +100% урона по более дальним целям) и исцеляет вас на 0,5% максимального здоровья за врага (до 2%).", -- bonk_weapon 517
    ["Holy Word: Sanctify"] = "Свет поражает сильнейшего врага поблизости (сначала элиту) большим уроном, задевает врагов в 8 ярдах половиной урона и исцеляет вас на 3% максимального здоровья. «Наказание» и «Кольцо света» сокращают перезарядку на 1 сек.", -- bonk_weapon 518
    ["Apotheosis"] = "Свет поражает сильнейшего врага поблизости (сначала элиту) большим уроном и сбрасывает перезарядку «Наказания» и «Кольца света». Каждое из них сокращает перезарядку «Апофеоза» на 1 сек.", -- bonk_weapon 519
    ["Reflective Shield"] = "Создаёт щит на 10% максимального здоровья; повторное применение пополняет его. Пока щит действует, скорость движения +10%. Поглощённый урон возвращается атакующему уроном света.", -- bonk_weapon 520
    ["Power Word: Barrier"] = "Создаёт щит на 10% максимального здоровья и купол на 5 сек. Внутри купола вы получаете на 25% меньше урона. Повторное применение пополняет щит; пока он действует, скорость движения +10%.", -- bonk_weapon 521
    ["Rapture"] = "Выпускает 3 световые стрелы во врагов, атаковавших вас недавно, либо 5 при наличии щита. Каждая наносит урон света и исцеляет на 0,5% максимального здоровья. Избыточное исцеление становится щитом.", -- bonk_weapon 522
    ["Contrition"] = "Выпускает 3 световые стрелы во врагов, атаковавших вас недавно. Каждая наносит урон света, задевает врагов в 4 ярдах половиной урона и исцеляет вас на 0,5% максимального здоровья. Избыточное исцеление становится щитом.", -- bonk_weapon 523
    ["Psychic Horror"] = "Обычные враги в 8 ярдах бегут в страхе 2 сек., каждую секунду получая урон тьмой, и получают на 20% больше всего урона. Элита и боссы не убегают.", -- bonk_weapon 524
    ["Shadow Terror"] = "Обычные враги в 8 ярдах бегут в страхе 2 сек., получают 3 эффекта разложения и ежесекундный урон тьмой. Элита и боссы не убегают.", -- bonk_weapon 525
    ["Chains of Light"] = "Связывает сильнейшего врага поблизости (сначала элиту) на 2 сек. и наносит урон светом при связывании и ежесекундно, а также увеличивает весь получаемый целью урон на 30%. Боссы не связываются, но получают первый удар.", -- bonk_weapon 526
    ["Mass Shackle"] = "Связывает 3 сильнейших врагов поблизости (сначала элиту) на 2 сек. и наносит урон светом при связывании и ежесекундно. Боссы и мини-боссы не связываются, но получают первый удар.", -- bonk_weapon 527
    ["Vampiric Touch"] = "Накладывает 6 эффектов разложения на 3 самых дальних врагов в 35 ярдах. Урон разложения исцеляет вас на 2% от нанесённого урона, до 1% максимального здоровья в секунду.", -- bonk_weapon 528
    ["Misery"] = "Накладывает 6 эффектов разложения и 1 эффект уязвимости к тьме на 3 самых дальних врагов в 35 ярдах.", -- bonk_weapon 529
    ["Mind Sear"] = "Истязает ближайшего врага уроном тьмы, задевая соседей в 6 ярдах половиной урона, накладывает разложение и замедляет на 30%. Урон +5% за эффект разложения (до 30).", -- bonk_weapon 530
    ["Insanity"] = "Истязает ближайшего врага уроном тьмы, накладывает разложение и замедляет на 30%. При смерти цели разложение переносится на следующего врага. Урон +5% за эффект разложения (до 30).", -- bonk_weapon 531
    ["Mind Spike"] = "Поражает уроном тьмы врага с наибольшим разложением. Все враги в 8 ярдах получают такое же количество эффектов (до 10), после чего цель мгновенно получает весь оставшийся урон своего разложения.", -- bonk_weapon 532
    ["Void Eruption"] = "Поражает уроном тьмы врага с наибольшим разложением. Все враги в 8 ярдах получают половину урона и столько же эффектов разложения (до 10).", -- bonk_weapon 533
    ["Mindbender"] = "Призывает исчадие Тьмы, чьи атаки бьют врагов в 5 ярдах от цели, накладывают разложение и исцеляют вас на 0,5% максимального здоровья.", -- bonk_weapon 534
    ["Void Tendrils"] = "Призывает исчадие Тьмы, чьи удары накладывают разложение и исцеляют вас на 0,5% максимального здоровья. Каждые 6 сек. исчадие опутывает обычных врагов в радиусе 6 ярдов на 2 сек.", -- bonk_weapon 535
    ["Frostbolt"] = "Выпускает ледяную стрелу в ближайшего врага, нанося урон льдом и накладывая 1 эффект охлаждения. По замороженным врагам урон выше на 50%; ваши заклинания льда всегда критически поражают их.", -- bonk_weapon 400
    ["Blizzard"] = "4 сек. ледяные осколки обрушиваются на крупнейшую группу врагов, каждую секунду нанося урон льдом и накладывая 1 эффект охлаждения.", -- bonk_weapon 401
    ["Frost Nova"] = "Поражает всех врагов в радиусе 10 ярдов от вас уроном льдом и накладывает 3 эффекта охлаждения.", -- bonk_weapon 402
    ["Fireball"] = "Бросает огненный шар в ближайшего врага, нанося урон огнём и накладывая 2 эффекта горения.", -- bonk_weapon 403
    ["Flamestrike"] = "Обрушивает огненный столб на крупнейшую группу врагов, нанося урон огнём и накладывая 4 эффекта горения. Земля горит ещё 4 сек. и наносит урон врагам внутри.", -- bonk_weapon 404
    ["Pyroblast"] = "Бросает огромный огненный шар в элитного врага, босса или крупнейшую группу, нанося цели большой урон огнём и 35% этого урона врагам в радиусе 6 ярдов.", -- bonk_weapon 405
    ["Fire Blast"] = "Поражает 3 врагов с наибольшим числом эффектов горения уроном огня. Урон +10% за эффект горения (до 30).", -- bonk_weapon 406
    ["Blink"] = "Рывок превращается в «Скачок»: телепортация с дополнительным зарядом и перезарядкой на 30% короче. В месте старта происходит чародейский взрыв в 10 ярдах; в месте приземления враги получают 2 эффекта охлаждения, а «Кольцо льда» снова готово. Занимает ячейку заклинания.", -- bonk_weapon 407
    ["Arcane Explosion"] = "Взрыв тайной магии поражает всех врагов в радиусе 10 ярдов. Также срабатывает при приземлении после каждого «Скачка».", -- bonk_weapon 408
    ["Arcane Missiles"] = "За 1 сек. выпускает 5 чародейских стрел в ближайшего врага. После «Скачка» все 5 стрел выпускаются одновременно в ближайших врагов.", -- bonk_weapon 409
    ["Summon Elemental"] = "Призывает элементаля, который сражается за вас. Его стихия соответствует преобладающей школе ваших заклинаний.", -- bonk_weapon 410
    ["Ice Shards"] = "Ледяная стрела наносит урон льдом, накладывает охлаждение и причиняет замороженным врагам на 50% больше урона. Перескакивает между замороженными целями в 12 ярдах до 6 раз. По замороженным врагам заклинания льда всегда критические.", -- bonk_weapon 411
    ["Shatter"] = "Ледяная стрела наносит урон льдом, накладывает охлаждение и наносит +50% урона замороженным врагам. По замороженной цели осколки бьют врагов в радиусе 5 ярдов тем же уроном. Заклинания льда по замороженным целям всегда критические.", -- bonk_weapon 412
    ["Deep Freeze"] = "4 сек. ледяные осколки поражают крупнейшую группу врагов уроном льда и накладывают охлаждение каждую секунду. Замороженные внутри обычные враги остаются замороженными до конца действия.", -- bonk_weapon 413
    ["Frostbite"] = "4 сек. ледяные осколки поражают крупнейшую группу врагов уроном льда и накладывают охлаждение каждую секунду. Каждая заморозка отнимает у обычного врага 15% максимального здоровья (у элиты 5%, у боссов 1%).", -- bonk_weapon 414
    ["Ice Nova"] = "Взрывает лёд вокруг последней цели «Ледяной стрелы» или ближайшего врага в 30 ярдах, поражая всех в 10 ярдах уроном льда и накладывая 3 эффекта охлаждения.", -- bonk_weapon 415
    ["Ice Barrier"] = "Поражает всех врагов в 10 ярдах уроном льда и накладывает 3 эффекта охлаждения. Каждый замороженный враг даёт щит на 1% максимального здоровья, до 15% за применение.", -- bonk_weapon 416
    ["Wildfire"] = "Огненный шар поражает ближайшего врага и накладывает 2 эффекта горения. Пока цель жива, в течение 6 сек. её горение раз в секунду перескакивает на соседнего ещё не горящего врага.", -- bonk_weapon 417
    ["Living Bomb"] = "Огненный шар поражает ближайшего врага и накладывает 2 эффекта горения. Через 2 сек. бомба взрывается, нанося 50% урона и накладывая 2 эффекта горения врагам в 6 ярдах.", -- bonk_weapon 418
    ["Firewalk"] = "Последовательно обрушивает 3 огненных столба через крупнейшую группу врагов. Каждый наносит урон огнём и накладывает 4 эффекта горения. Земля после каждого столба горит 4 сек.", -- bonk_weapon 419
    ["Burning Ground"] = "Обрушивает огненный столб на крупнейшую группу врагов, нанося урон огнём и 4 эффекта горения. Пламя наносит урон 4 сек., а земля горит 6 сек., накладывая по 1 эффекту горения в секунду всем в радиусе 8 ярдов.", -- bonk_weapon 420
    ["Meteor"] = "Метеор падает на крупнейшую группу врагов, нанося большой урон огнём и накладывая 2 эффекта горения в 8 ярдах. Кратер горит 4 сек., каждую секунду накладывая горение на врагов в 5 ярдах.", -- bonk_weapon 421
    ["Meteor Shower"] = "7 метеоров падают на крупнейшую группу врагов. Каждый наносит урон огнём в радиусе 3 ярдов, повышенный на 10% за эффект горения (до 30).", -- bonk_weapon 422
    ["Blast Wave"] = "Огненная волна поражает всех врагов в 10 ярдах от вас. Урон +10% за эффект горения (до 30). Каждый горящий враг, задетый волной, взрывается с 40% урона по 3 врагам в 5 ярдах.", -- bonk_weapon 423
    ["Hot Streak"] = "Поражает 3 врагов с наибольшим горением уроном огня (+10% за эффект, до 30). Первый критический удар за применение мгновенно активирует «Огненную глыбу» или выпускает её в цель, если заклинание не изучено.", -- bonk_weapon 424
    ["Phase Rush"] = "Рывок становится «Скачком»: +1 заряд и −30% перезарядки. В точке старта происходит взрыв тайной магии в 10 ярдах, все враги по пути поражаются, а вы неуязвимы на 1 сек. В месте приземления враги получают 2 эффекта охлаждения и сбрасывается перезарядка «Кольца льда».", -- bonk_weapon 425
    ["Shimmer"] = "Рывок становится «Скачком»: +3 заряда и −30% перезарядки. В точке старта происходит взрыв тайной магии в 10 ярдах и сбрасывается перезарядка «Чародейского взрыва». В месте приземления враги получают 2 эффекта охлаждения, а «Кольцо льда» снова готово.", -- bonk_weapon 426
    ["Slow Time"] = "Взрыв тайной магии поражает всех врагов в 10 ярдах, в том числе при приземлении после «Скачка». После взрыва на 10 сек. остаётся пузырь времени: обычные враги внутри замедлены на 60%, все враги получают на 15% больше урона.", -- bonk_weapon 427
    ["Presence of Mind"] = "Взрыв тайной магии поражает всех врагов в 10 ярдах, в том числе при приземлении после «Скачка». Каждый взрыв мгновенно применяет одно из других ваших заклинаний не чаще раза в 0,5 сек.", -- bonk_weapon 428
    ["Arcane Barrage"] = "За 1 сек. выпускает 5 чародейских стрел. При наличии «Скачка» стрелы копятся во время движения (до 40), а следующий «Скачок» выпускает все накопленные стрелы в ближайших врагов.", -- bonk_weapon 429
    ["Arcane Power"] = "За 1 сек. выпускает 5 чародейских стрел. После каждого «Скачка» все 5 стрел выпускаются разом в ближайших врагов, а урон ваших заклинаний увеличивается на 30% на 4 сек.", -- bonk_weapon 430
    ["Hydra"] = "Призывает трёхглавую гидру, стреляющую ледяными, огненными и чародейскими снарядами во врагов в 30 ярдах. Каждая голова выбирает отдельную цель; лёд накладывает охлаждение, огонь — горение. Гидра следует за вами при удалении.", -- bonk_weapon 431
    ["Elemental Shift"] = "Призывает элементаля, меняющего стихию каждые 5 сек.: вода накладывает охлаждение, огонь — горение, затем следует тайная магия.", -- bonk_weapon 432
    ["Cleave"] = "Наносит урон всем врагам в пределах 10 ярдов от вас.", -- bonk_weapon 300
    ["Rend"] = "Ранит 3 ближайших врагов в 10 ярдах, накладывая по 3 эффекта кровотечения. Попадания «Рассекающего удара», «Вихря» и «Удара грома» дополнительно накладывают кровотечение.", -- bonk_weapon 301
    ["Deep Wounds"] = "Критические удары накладывают 2 эффекта кровотечения, не чаще раза в 0,5 сек. на врага. Шанс критического удара по истекающему кровью врагу повышается на 1% за эффект (до 20%).", -- bonk_weapon 302
    ["Mortal Strike"] = "Бьёт всех врагов в 10 ярдах. Урон +8% за эффект кровотечения на цели (до 30). Кровоточащие враги дополнительно получают оставшийся урон кровотечения за 2 сек., сохраняя эффекты.", -- bonk_weapon 303
    ["Bloodthirst"] = "Бьёт 3 ближайших врагов в 10 ярдах и исцеляет вас на 0,5% максимального здоровья за цель (до 2,5%). Критические удары вызывают исступление: +25% скорости действий на 4 сек.", -- bonk_weapon 304
    ["Execute"] = "Бьёт всех врагов в 10 ярдах. Обычные враги с менее чем 20% здоровья гибнут мгновенно; элита и боссы получают тройной урон. Убийства вызывают исступление: +25% скорости действий на 4 сек.", -- bonk_weapon 305
    ["Whirlwind"] = "Кружась, наносит урон всем врагам в 8 ярдах от вас. Во время исступления вращается дважды.", -- bonk_weapon 306
    ["Shield Block"] = "Даёт щит на 10% максимального здоровья, действующий до поглощения урона. Щиты складываются до 50% здоровья.", -- bonk_weapon 307
    ["Thunder Clap"] = "Громовой удар поражает всех врагов в 8 ярдах и замедляет их атаки на 20% на 6 сек.", -- bonk_weapon 308
    ["Revenge"] = "При получении удара атакует всех врагов в радиусе 10 ярдов от вас, не чаще раза в 2 сек.", -- bonk_weapon 309
    ["Shield Slam"] = "Бьёт всех врагов в 10 ярдах. Урон +2% за каждый 1% максимального здоровья в вашем щите (до +200%).", -- bonk_weapon 310
    ["Wake of Blades"] = "Бьёт всех врагов в 8 ярдах. После каждого взмаха через 1 сек. срабатывает повторный удар-эхо.", -- bonk_weapon 311
    ["Fourth Swing"] = "Бьёт всех врагов в 8 ярдах. Каждый четвёртый удар достигает 12 ярдов и отбрасывает обычных врагов.", -- bonk_weapon 312
    ["Blood Aura"] = "Все враги в 8 ярдах от вас получают 2 эффекта кровотечения. «Рассекающий удар», «Вихрь» и «Удар грома» также накладывают по 1 эффекту.", -- bonk_weapon 313
    ["Blood Pool"] = "Наносит урон 3 ближайшим врагам в 10 ярдах и накладывает по 3 эффекта кровотечения. Умирающие от кровотечения враги оставляют лужу крови на 4 сек., накладывающую по 1 эффекту в секунду всем в 4 ярдах. Ваши удары по площади тоже накладывают кровотечение.", -- bonk_weapon 314
    ["Bloodsplatter"] = "Критические удары накладывают 2 эффекта кровотечения на цель и врагов в 4 ярдах (не чаще раза в 0,5 сек. на врага). Шанс крита по кровоточащим целям +1% за эффект (до 20%).", -- bonk_weapon 315
    ["Hemorrhage"] = "Критические удары накладывают 2 эффекта кровотечения (не чаще раза в 0,5 сек.). Каждый тик этого кровотечения усиливается на 10%, максимум втрое. Шанс крита по кровоточащей цели +1% за эффект (до 20%).", -- bonk_weapon 316
    ["Bloodlust"] = "Бьёт всех врагов в 8 ярдах с +8% урона за эффект кровотечения (до 30). Каждая кровоточащая цель сокращает перезарядку на 0,5 сек. (до 1 сек. за удар, минимум до 3 сек.). Дополнительно мгновенно наносит урон кровотечения за 2 сек., сохраняя эффекты.", -- bonk_weapon 317
    ["Aftershock"] = "Бьёт всех врагов в 8 ярдах с +8% урона за эффект кровотечения (до 30). Через 1,5 сек. земля взрывается на 30% урона и накладывает кровотечение в 8 ярдах. Кровоточащие цели получают урон кровотечения за 2 сек. немедленно, сохраняя эффекты.", -- bonk_weapon 318
    ["Blood Shield"] = "Поражает 3 ближайших врагов в 8 ярдах и исцеляет на 0,5% максимального здоровья за цель (до 2,5%). Избыточное исцеление становится кровавым щитом; при разрушении щит взрывается с 200% урона в 8 ярдах.", -- bonk_weapon 319
    ["Bloodbath"] = "Поражает 3 ближайших врагов в 8 ярдах и исцеляет на 0,5% здоровья за цель (до 2,5%). При здоровье ниже 50% поражает всех врагов в 8 ярдах и исцеляет максимум на 4%.", -- bonk_weapon 320
    ["Chain Execution"] = "Бьёт всех врагов в 8 ярдах. Обычные враги с менее чем 20% здоровья гибнут мгновенно, элита и боссы получают тройной урон. Убийства вызывают взрыв на 50% урона в 5 ярдах и добивают обычных врагов ниже 20%, а также вводят вас в исступление.", -- bonk_weapon 321
    ["Sweep"] = "Бьёт всех врагов в 8 ярдах. Элита и боссы с менее 20% здоровья получают тройной урон; обычные враги ниже 20% здоровья в 40 ярдах гибнут мгновенно. Убийства вызывают исступление: +25% скорости действий на 4 сек.", -- bonk_weapon 322
    ["Bladestorm"] = "3 сек. вращается во время движения и каждые 0,5 сек. бьёт всех врагов в 8 ярдах. Скорость действий увеличивает частоту ударов. В состоянии исступления длительность вращения увеличена на 50%.", -- bonk_weapon 323
    ["Steel Cyclone"] = "Вращается, поражая врагов в 8 ярдах; при исступлении — дважды. Каждый удар оставляет вихрь клинков на 3 сек., наносящий врагам в 8 ярдах по 20% урона каждые 0,5 сек.", -- bonk_weapon 324
    ["Aegis"] = "Даёт щит на 10% максимального здоровья до поглощения урона. Каждое поглощённое попадание вызывает ударную волну, наносящую урон всем врагам в 8 ярдах, не чаще раза в 0,5 сек.", -- bonk_weapon 325
    ["Spiked Shield"] = "Даёт щит на 10% максимального здоровья до поглощения урона. Пока у вас есть любой щит, шипы каждую секунду поражают всех врагов в 8 ярдах.", -- bonk_weapon 326
    ["Rolling Thunder"] = "Громовой удар поражает всех врагов в 8 ярдах, но активируется другими вашими заклинаниями, а не перезарядкой. Попадания замедляют атаки врагов на 20% на 6 сек. Скорость действий уменьшает число требуемых применений, минимум до 4.", -- bonk_weapon 327
    ["Demoralizing Shout"] = "Громовой удар бьёт всех врагов в 8 ярдах и на 6 сек. снижает скорость их атак и наносимый ими урон на 20%. Исцеляет вас на 0,3% максимального здоровья за цель (до 2%).", -- bonk_weapon 328
    ["Vengeance"] = "Когда вас бьют, наносит урон всем врагам в 6 ярдах, не чаще раза в 2 сек. Полученный здоровьем урон накапливается до 50% максимального здоровья и увеличивает урон следующего удара до +200%.", -- bonk_weapon 329
    ["Berserker Rage"] = "Когда вас бьют, поражает всех врагов в 6 ярдах и вводит в исступление (+25% скорости действий на 4 сек.), не чаще раза в 2 сек.", -- bonk_weapon 330
    ["Bulwark"] = "Бьёт всех врагов в 6 ярдах с +2% урона за каждый 1% максимального здоровья в вашем щите (до +200%). Каждое попадание добавляет щиту 1% максимального здоровья (до 10% за удар).", -- bonk_weapon 332
    ["Arcane Shot"] = "Стреляет в ближайшего врага, нанося урон тайной магией.", -- bonk_weapon 7
    ["Multi-Shot"] = "Поражает до 6 врагов в пределах 18 ярдов конусом в направлении ближайшего врага.", -- bonk_weapon 37
    ["Serpent Sting"] = "Поражает ближайшего врага и 2 цели рядом с ним, накладывая по 3 эффекта яда.", -- bonk_weapon 38
    ["Volley"] = "4 сек. осыпает стрелами крупнейшую группу врагов в 20 ярдах. Урон +5% за каждый различный отрицательный эффект на цели. Каждые 25 попаданий заряжают «Прицельный выстрел» взрывной стрелой (до 2).", -- bonk_weapon 137
    ["Call Pet"] = "Призывает боевого кота. Его удары накладывают по 1 эффекту кровотечения, «Когти» — 4 эффекта, а «Размах» бьёт всех врагов перед ним.", -- bonk_weapon 201
    ["Explosive Trap"] = "Ставит огненную ловушку, которая взрывается при приближении врага. Наносит урон и оставляет горящую землю на 4 сек., накладывающую горение.", -- bonk_weapon 202
    ["Aimed Shot"] = "Выстрел пробивает всех врагов по прямой, целясь в группу с метками или крупнейшую группу. Заряженная взрывная стрела взрывается при первом попадании и поражает всех в 8 ярдах.", -- bonk_weapon 203
    ["Viper Trap"] = "Ставит ловушку, выпускающую 4 змей при приближении врага. Каждая змея бросается к одной из 4 ближайших целей и создаёт ядовитое облако на 4 сек. Враги внутри получают по 1 эффекту яда каждые 0,5 сек.", -- bonk_weapon 204
    ["Hunter's Mark"] = "На 8 сек. отмечает всех врагов в 10 ярдах от крупнейшей группы. Отмеченные получают на 15% больше урона.", -- bonk_weapon 205
    ["Pack Leader"] = "Призывает боевого духовного волка. Каждые 15 сек. волк воет, удваивая урон других питомцев по врагам перед ними на 6 сек. Укусы питомцев накладывают метку охотника.", -- bonk_weapon 211
    ["Chimera Shot"] = "Наносит ближайшему врагу урон тайной магией и поглощает все эффекты яда на цели, мгновенно нанося оставшийся урон отравления.", -- bonk_weapon 212
    ["Ricochet"] = "Стреляет в ближайшего врага уроном тайной магии, затем перескакивает ещё на 2 врагов в 10 ярдах, сначала по отмеченным. Каждый переход наносит на 25% больше урона предыдущего.", -- bonk_weapon 213
    ["Trick Shots"] = "Выпускает 3 стрелы конусом перед вами. Каждый убитый ими враг выпускает по 3 стрелы в ближайшие цели в 15 ярдах. Последующие убийства продолжают цепь.", -- bonk_weapon 214
    ["Serpent Spread"] = "Выпускает 3 стрелы конусом перед вами, нанося урон и накладывая по 2 эффекта яда.", -- bonk_weapon 215
