local WARRIOR_AVENGERS_SHIELD = "Бросает щит в ближайшего врага в 20 ярдах. Щит перескакивает ещё на 5 целей в 10 ярдах без повторов. Урон +2% за каждый 1% максимального здоровья в вашем щите (до +200%)."
local PALADIN_AVENGERS_SHIELD = "Бросает освящённый щит в ближайшего врага в 25 ярдах. Щит перескакивает ещё на 4 врагов в пределах 10 ярдов без повторных попаданий. Каждое попадание считается ударом паладина."

-- Shapeshift and both evolutions are shared between client and server; the text
-- may contain WoW |n markers or real newlines. Preserve the colour markup.
local function TranslateForms(raw)
    if type(raw) ~= "string" or not string.find(raw, "Press R to shift into your next form", 1, true) then
        return nil
    end
    local parts = {
        "R — следующий облик. В своём облике заклинания друида наносят на 30% больше урона и сильнее исцеляют.",
        "|cffffffffЛунный совух:|r Гнев бьёт ближайшую цель уроном природы и задевает врагов поблизости. Раз в 3 сек. Звездопад поражает 3 цели с Лунным огнём.",
        "|cffffffffКошка:|r Когти бьют ближайшего врага и накладывают кровотечение. Скорость движения +15%, критические удары накладывают кровотечение.",
        "|cffffffffМедведь:|r Увечье бьёт ближайшего врага. Получаемый урон −35%, урон заклинаний других обликов −20%. Размах: +8% урона за врага рядом. Раз в 6 сек. рёв ошеломляет врагов и снижает их урон на 25%.",
        "|cffffffffДрево жизни:|r Лозы бьют 3 ближайших врагов уроном природы, исцеляя вас на 0,3% макс. здоровья за попадание. +1 древень; Омоложение созревает на 50% быстрее.",
    }
    if string.find(raw, "Attacks 50% faster", 1, true) then
        parts[3] = "|cffffffffКошка:|r Когти бьют ближайшего врага и врагов в 5 ярдах, накладывая кровотечение. Атаки на 50% быстрее, скорость движения +15%. Критические удары накладывают кровотечение."
    end
    if string.find(raw, "spells of other forms deal and heal 20% less", 1, true) then
        parts[4] = "|cffffffffМедведь:|r Увечье бьёт ближайшего врага и врагов в 5 ярдах. Получаемый урон −35%; урон и исцеление других обликов −20%. Размах: +8% урона за врага в 8 ярдах (до 8). Раз в 6 сек. рёв ошеломляет врагов в 10 ярдах и снижает их урон на 25% на 4 сек."
    end
    if string.find(raw, "Shifting Surge:", 1, true) then
        table.insert(parts,"|cffffffffВолна превращений:|r Раз в 6 сек. при смене облика: совух обрушивает Звездопад на 5 врагов; кошка накладывает 2 кровотечения; медведь рычит; древо опутывает врагов и исцеляет вас на 2% макс. здоровья.")
    elseif string.find(raw, "Spirit Forms:", 1, true) then
        table.insert(parts,"|cffffffffДуховные формы:|r Предыдущий облик остаётся духом на 6 сек. и атакует с 25% урона.")
    end
    return table.concat(parts, "|n|n")
end

local function MatchDescription(name, original)
    if type(original) ~= "string" or original == "" then return nil end
    if string.find(original, "Press R to shift into your next form", 1, true) then
        return TranslateForms(original)
    end
    if name == "Avenger's Shield" then
        if string.find(original, "holy shield", 1, true) then
            return PALADIN_AVENGERS_SHIELD
        end
        return WARRIOR_AVENGERS_SHIELD
    end
    if type(name) == "string" then
        local direct = RU_ABILITY_DESCRIPTIONS[name]
        if direct then return direct end
        -- Some server configurations already send Russian names.
        local locale = VanillaBonkLocale
        if type(locale) == "table" and type(locale.English) == "function" then
            local ok, english = pcall(locale.English, name)
            if ok and type(english) == "string" then return RU_ABILITY_DESCRIPTIONS[english] end
        end
    end
    return nil
end

local skillTitle
local installedTip = false
local installedOffers = false
local function InstallAbilities()
    local tip = VanillaBonkSpellTip
    if not installedTip and type(tip) == "table" and type(tip.Title) == "function" and type(tip.AddLine) == "function" then
        installedTip = true
        if type(tip.SetOwner) == "function" then
            local oldOwner = tip.SetOwner
            tip.SetOwner = function(self, target, anchor)
                skillTitle = nil
                return oldOwner(self, target, anchor)
            end
        end
        local oldTitle = tip.Title
        tip.Title = function(self, name, color, tags)
            -- Hook after FullData: capture the original name before it is localized.
            skillTitle = name
            return oldTitle(self, name, color, tags)
        end
        local oldLine = tip.AddLine
        tip.AddLine = function(self, text, r, g, b)
            -- Gold-coloured lines are gameplay descriptions, not flavour text.
            if type(text) == "string" and type(r) == "number" and type(g) == "number" and type(b) == "number" and
               r >= 0.95 and g >= 0.75 and g <= 0.9 and b <= 0.1 then
                local translated = MatchDescription(skillTitle, text)
                if translated then text = translated end
            end
            return oldLine(self, text, r, g, b)
        end
    end
    local offer = VanillaBonkOffer
    if not installedOffers and type(offer) == "table" and type(offer.FitCard) == "function" then
        installedOffers = true
        local originalFit = offer.FitCard
        offer.FitCard = function(card, choice, width, hasLock)
            if type(choice) == "table" and type(choice.description) == "string" then
                local translated = MatchDescription(choice.name, choice.description)
                if translated then
                    local clone = {}
                    for k, v in pairs(choice) do clone[k] = v end
                    clone.description = translated
                    return originalFit(card, clone, width, hasLock)
                end
            end
            return originalFit(card, choice, width, hasLock)
        end
    end
end

InstallAbilities()
local installer = CreateFrame("Frame", "HordesRUAbilityInstaller112")
local lastTry = 0
installer:SetScript("OnUpdate", function()
    local now = GetTime()
    if now - lastTry > 2 then
        lastTry = now
        if not installedTip or not installedOffers then InstallAbilities() end
    end
end)